const assert = require('node:assert/strict');
const fs = require('node:fs'); const http = require('node:http'); const path = require('node:path'); const { chromium } = require('playwright');
const prototypeDir = __dirname; const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe'; const missingRequests = []; let lastUrl = '', runId = 0;
function startServer(){const types={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8'};const server=http.createServer((request,response)=>{const relative=request.url==='/'?'index.html':request.url.split('?')[0].replace(/^\//,'');const file=path.resolve(prototypeDir,relative);if(!file.startsWith(prototypeDir+path.sep)&&file!==path.join(prototypeDir,'index.html'))return response.writeHead(403).end('Forbidden');fs.readFile(file,(error,content)=>{if(error){missingRequests.push(relative);return response.writeHead(404).end('Not found')}response.writeHead(200,{'Content-Type':types[path.extname(file)]||'application/octet-stream'});response.end(content)})});return new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,'127.0.0.1',()=>resolve(server))})}
async function product(page,url,scenario){if(url)lastUrl=url;else await page.goto('about:blank');const target=url||`${lastUrl}${lastUrl.includes('?')?'&':'?'}testRun=${++runId}`;await page.goto(target,{waitUntil:'networkidle'});if(scenario)await page.getByRole('button',{name:scenario,exact:true}).click();await page.addStyleTag({content:'.prototype-toolbar,.review-note{display:none!important}.stage{display:block!important;width:100%!important;margin:0!important}.phone{width:100%!important;height:100vh!important;padding:0!important;border:0!important;border-radius:0!important;box-shadow:none!important}.phone-notch{display:none!important}.mobile-edit-surface,#layer-root{border-radius:0!important}#layer-root{inset:0!important}'})}
async function noOverflow(page,width,label){assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth),true,`${width}px ${label} has no page overflow`);assert.equal(await page.locator('#app-root').evaluate(element=>element.scrollWidth<=element.clientWidth),true,`${width}px ${label} has no editor overflow`)}
async function targets(page,label){const undersized=await page.locator('#app-root button,#layer-root button').evaluateAll(buttons=>buttons.map(button=>{const r=button.getBoundingClientRect();return{name:button.getAttribute('aria-label')||button.textContent.trim(),width:Math.round(r.width),height:Math.round(r.height)}}).filter(x=>x.width<44||x.height<44));assert.deepEqual(undersized,[],`${label} has 44px targets: ${JSON.stringify(undersized)}`)}
async function expectDialogFocusAndTrap(page,title){const dialog=page.getByRole('dialog',{name:title,exact:true});assert.equal(await dialog.count(),1,`${title} dialog opens`);assert.equal(await page.locator('.prototype-toolbar').evaluate(el=>el.inert),true,`${title} makes prototype controls inert`);assert.equal(await page.locator('#app-root').evaluate(el=>el.inert),true,`${title} makes product background inert`);assert.equal(await dialog.getByRole('button',{name:'Close',exact:true}).evaluate(el=>document.activeElement===el),true,`${title} starts focus on Close`);await page.keyboard.press('Shift+Tab');assert.equal(await dialog.locator('button').last().evaluate(el=>document.activeElement===el),true,`${title} traps Shift+Tab at the first control`);await page.keyboard.press('Tab');assert.equal(await dialog.getByRole('button',{name:'Close',exact:true}).evaluate(el=>document.activeElement===el),true,`${title} traps Tab at the final control`)}
async function basics(page,width){assert.equal(await page.getByRole('heading',{name:'5 issues need attention',exact:true}).count(),1,`${width}px has Save summary`);assert.equal(await page.getByRole('button',{name:/Basics, 4 errors/}).count(),1,`${width}px marks Basics`);assert.equal(await page.getByRole('button',{name:/Ingredients, 1 error/}).count(),1,`${width}px shows only recipe-level Ingredients error`);await page.getByRole('link',{name:'Enter servings as a whole number.',exact:true}).click();assert.equal(await page.locator('#servings').evaluate(el=>document.activeElement===el),true,`${width}px summary focuses field`);assert.equal(await page.locator('#servings').getAttribute('aria-invalid'),'true',`${width}px field has invalid state`);await page.getByRole('link',{name:'Remove 2 ingredients before saving.',exact:true}).click();assert.equal(await page.locator('#ingredients').evaluate(el=>document.activeElement===el),true,`${width}px Ingredients summary link focuses section target`);assert.equal(await page.getByRole('button',{name:'Add ingredient',exact:true}).isDisabled(),true,`${width}px disables Add ingredient at capacity`)}
async function ingredients(page,width){const row=page.getByRole('button',{name:/Chickpeas/});await row.click();await expectDialogFocusAndTrap(page,'Edit ingredient');await page.getByRole('button',{name:'Done',exact:true}).click();await page.waitForFunction(()=>document.activeElement?.id==='ingredient');assert.equal(await page.locator('#ingredient').evaluate(el=>document.activeElement===el),true,`${width}px Done focuses first invalid ingredient field`);assert.equal(await page.locator('#ingredient').getAttribute('aria-describedby'),'ingredient-error',`${width}px associates ingredient error`);assert.equal(await page.locator('#quantity').getAttribute('aria-describedby'),'quantity-error',`${width}px associates quantity error`);assert.equal(await page.locator('.field-error',{hasText:'Enter an ingredient name.'}).count(),1,`${width}px shows ingredient required error`);assert.equal(await page.getByRole('button',{name:/Ingredients, 1 error/}).count(),1,`${width}px keeps local subdraft errors out of recipe count`);await page.getByRole('button',{name:'Close',exact:true}).click()}
async function guard(page,width){if(await page.getByRole('dialog',{name:'Unsaved changes',exact:true}).count()===0)await page.getByRole('button',{name:'Back to recipe',exact:true}).click();await expectDialogFocusAndTrap(page,'Unsaved changes');await page.getByRole('button',{name:'Save changes',exact:true}).click();await page.waitForFunction(()=>document.activeElement?.classList.contains('error-summary'));assert.equal(await page.locator('.error-summary').evaluate(el=>document.activeElement===el),true,`${width}px failed guard Save focuses summary`);for(const [index,trigger] of ['View recipe','Cooking focus','Manage media'].entries()){if(index===0)await page.getByRole('button',{name:'More recipe actions',exact:true}).click();await page.getByRole('button',{name:trigger,exact:true}).click();await expectDialogFocusAndTrap(page,'Unsaved changes');await page.getByRole('button',{name:'Keep editing',exact:true}).click()}for(const trigger of ['Recipes','Add recipe']){await page.getByRole('button',{name:trigger,exact:true}).click();await expectDialogFocusAndTrap(page,'Unsaved changes');await page.getByRole('button',{name:'Keep editing',exact:true}).click()}await page.getByRole('button',{name:'Media',exact:true}).click();assert.equal(await page.getByRole('dialog').count(),0,`${width}px Media does not invoke guard`);await page.getByRole('button',{name:'More recipe actions',exact:true}).click();await page.getByRole('button',{name:'Import info',exact:true}).click();assert.equal(await page.getByRole('dialog').count(),0,`${width}px Import info does not invoke guard`);await page.goBack();await expectDialogFocusAndTrap(page,'Unsaved changes');assert.equal(page.url().startsWith(lastUrl),true,`${width}px first real browser Back remains in Edit`);await page.getByRole('button',{name:'Discard changes',exact:true}).click();assert.equal(await page.getByText('Recipe view restored for this prototype.').count(),1,`${width}px only Discard exits`)}
async function hybrid(page,width){await product(page,'',null);assert.equal(await page.locator('.error-summary').count(),0,`${width}px has no summary before Save`);await page.locator('#title').focus();await page.locator('#title').blur();assert.equal(await page.locator('.field-error',{hasText:'Enter a recipe title.'}).count(),1,`${width}px required title validates on blur`);await page.locator('#time').fill('4x');assert.equal(await page.locator('#time').getAttribute('aria-invalid'),'true',`${width}px impossible time validates immediately`);await page.locator('#time').fill('45');assert.equal(await page.locator('#time').getAttribute('aria-invalid'),null,`${width}px corrected time clears immediate error`);await page.getByRole('button',{name:'Save recipe',exact:true}).click();await page.locator('#author').fill('Marta Cooks');assert.equal(await page.getByRole('heading',{name:'3 issues need attention',exact:true}).count(),1,`${width}px summary total updates while correcting`);assert.equal(await page.getByRole('heading',{name:'Basics · 2',exact:true}).count(),1,`${width}px summary section count updates while correcting`);assert.equal(await page.locator('#author').evaluate(el=>document.activeElement===el),true,`${width}px summary sync preserves field focus`);await page.getByRole('button',{name:/Ingredients/}).click();const row=page.getByRole('button',{name:/Chickpeas/});await row.click();await page.locator('#quantity').fill('/');assert.equal(await page.locator('#quantity').getAttribute('aria-invalid'),'true',`${width}px rejects bare slash quantity`);await page.locator('#quantity').fill('1/');assert.equal(await page.locator('#quantity').getAttribute('aria-invalid'),null,`${width}px defers plausible partial fraction`);await page.locator('#quantity').blur();assert.equal(await page.locator('#quantity').getAttribute('aria-invalid'),'true',`${width}px validates partial fraction on blur`);await page.locator('#quantity').fill('1/2');assert.equal(await page.locator('#quantity').getAttribute('aria-invalid'),null,`${width}px accepts fraction quantity`);await page.locator('#ingredient').fill('Chickpeas');await page.getByRole('button',{name:'Close',exact:true}).click();assert.equal(await row.evaluate(el=>document.activeElement===el),true,`${width}px restores focus to current ingredient row after typing`);await page.getByRole('button',{name:'Remove 2 ingredients',exact:true}).click();await page.getByRole('button',{name:/Basics/}).click();for(const [id,value] of [['title','Smoky Tomato & Butter Bean Stew'],['author','Marta Cooks'],['time','45'],['servings','4']])await page.locator(`#${id}`).fill(value);const correctedState=await page.evaluate(()=>window.mobileEditValidationPrototype.getState());assert.deepEqual({overCapacity:correctedState.overCapacity,title:correctedState.fields.title,author:correctedState.fields.author,time:correctedState.fields.time,servings:correctedState.fields.servings},{overCapacity:false,title:'Smoky Tomato & Butter Bean Stew',author:'Marta Cooks',time:'45',servings:'4'},`${width}px corrected draft state reaches Save`);await page.getByRole('button',{name:'Save recipe',exact:true}).click();assert.equal(await page.getByText('Recipe saved for this prototype.').count(),1,`${width}px Save succeeds after corrections`)}
(async()=>{const server=await startServer();const browser=await chromium.launch({headless:true,executablePath:edgePath});try{const page=await browser.newPage();const url=`http://127.0.0.1:${server.address().port}/index.html`;const errors=[],consoleErrors=[],failed=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text())});page.on('response',r=>{if(r.status()>=400)failed.push(`${r.status()} ${r.url()}`)});for(const viewport of [{width:360,height:800},{width:390,height:844},{width:430,height:900}]){await page.setViewportSize(viewport);await product(page,url,'Basics errors');await noOverflow(page,viewport.width,'Basics');await targets(page,`${viewport.width}px Basics`);await basics(page,viewport.width);await ingredients(page,viewport.width);await product(page,url,'Unsaved-changes guard');await noOverflow(page,viewport.width,'guard');await targets(page,`${viewport.width}px guard`);await guard(page,viewport.width);await hybrid(page,viewport.width)}assert.deepEqual(errors,[],`page errors: ${errors.join(' | ')}`);assert.deepEqual(consoleErrors,[],`console errors: ${consoleErrors.join(' | ')}`);assert.deepEqual(failed,[],`failed resources: ${failed.join(' | ')}`);assert.deepEqual(missingRequests,[],`missing requests: ${missingRequests.join(' | ')}`);console.log('MOBILE_EDIT_VALIDATION_AND_GUARD_CHECKS_PASS')}finally{await browser.close();await new Promise(resolve=>server.close(resolve))}})().catch(e=>{console.error(e.stack||e);process.exitCode=1});
